import{_ as s,o as e,c as i,a2 as t}from"./chunks/framework.BXzK3EA4.js";const k=JSON.parse('{"title":"Ordenamiento Seguro y Desempate ↕️","description":"","frontmatter":{},"headers":[],"relativePath":"guide/sorting.md","filePath":"guide/sorting.md","lastUpdated":null}'),n={name:"guide/sorting.md"};function r(o,a,l,p,d,h){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="ordenamiento-seguro-y-desempate-↕️" tabindex="-1">Ordenamiento Seguro y Desempate ↕️ <a class="header-anchor" href="#ordenamiento-seguro-y-desempate-↕️" aria-label="Permalink to &quot;Ordenamiento Seguro y Desempate ↕️&quot;">​</a></h1><p>El ordenamiento de registros en APIs públicas es fundamental para tablas interactivas en el frontend. <strong>Laravel REST Processor</strong> ofrece ordenamiento seguro y páginas 100% deterministas.</p><hr><h2 id="🐣-1-comportamiento-por-defecto-cero-configuracion" tabindex="-1">🐣 1. Comportamiento por Defecto (Cero Configuración) <a class="header-anchor" href="#🐣-1-comportamiento-por-defecto-cero-configuracion" aria-label="Permalink to &quot;🐣 1. Comportamiento por Defecto (Cero Configuración)&quot;">​</a></h2><p>Si no configuras nada de ordenamiento:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> User</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">processRest</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">response</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>El procesador aplica automáticamente <strong><code>id desc</code></strong> por defecto.</p><ul><li>Los registros más recientes aparecen primero.</li><li>El orden es estable y consistente entre peticiones.</li></ul><hr><h2 id="🛡️-2-autorizar-columnas-para-ordenar-allowedsorts" tabindex="-1">🛡️ 2. Autorizar Columnas para Ordenar (<code>allowedSorts</code>) <a class="header-anchor" href="#🛡️-2-autorizar-columnas-para-ordenar-allowedsorts" aria-label="Permalink to &quot;🛡️ 2. Autorizar Columnas para Ordenar (`allowedSorts`)&quot;">​</a></h2><p>Para permitir que el usuario en el frontend haga clic en los encabezados de una tabla para ordenar:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark has-focused-lines vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> User</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">processRest</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>\n<span class="line has-focus"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    -&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">allowedSorts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;name&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;created_at&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]) </span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    -&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">response</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><hr><h2 id="🌐-3-peticiones-desde-el-frontend-prefijo" tabindex="-1">🌐 3. Peticiones desde el Frontend (Prefijo <code>-</code>) <a class="header-anchor" href="#🌐-3-peticiones-desde-el-frontend-prefijo" aria-label="Permalink to &quot;🌐 3. Peticiones desde el Frontend (Prefijo `-`)&quot;">​</a></h2><p>Siguiendo la convención REST universal, la dirección se determina por la presencia del signo menos (<code>-</code>):</p><table tabindex="0"><thead><tr><th>Petición HTTP</th><th>Dirección</th><th>Cláusula SQL</th></tr></thead><tbody><tr><td><code>?sort=name</code></td><td>Ascendente (A-Z, 0-9)</td><td><code>ORDER BY name asc</code></td></tr><tr><td><code>?sort=-name</code></td><td>Descendente (Z-A, 9-0)</td><td><code>ORDER BY name desc</code></td></tr></tbody></table><h3 id="ordenamiento-multiple" tabindex="-1">Ordenamiento Múltiple <a class="header-anchor" href="#ordenamiento-multiple" aria-label="Permalink to &quot;Ordenamiento Múltiple&quot;">​</a></h3><p>El cliente puede enviar múltiples columnas separadas por coma:</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/users?sort=-created_at,name</span></span></code></pre></div><p><strong>SQL generado:</strong></p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> created_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">desc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> asc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><hr><h2 id="⚙️-4-cambiar-el-orden-por-defecto-defaultsort" tabindex="-1">⚙️ 4. Cambiar el Orden por Defecto (<code>defaultSort</code>) <a class="header-anchor" href="#⚙️-4-cambiar-el-orden-por-defecto-defaultsort" aria-label="Permalink to &quot;⚙️ 4. Cambiar el Orden por Defecto (`defaultSort`)&quot;">​</a></h2><p>Si quieres que este endpoint ordene por otra columna cuando el cliente no especifique <code>?sort</code>:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark has-focused-lines vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> User</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">processRest</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    -&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">allowedSorts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;name&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;created_at&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">])</span></span>\n<span class="line has-focus"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    -&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">defaultSort</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;-created_at&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    -&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">response</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>También puedes especificar la dirección como segundo argumento:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">defaultSort</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;created_at&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;desc&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><hr><h2 id="🎯-5-desempate-determinista-automatico-primary-key-tie-breaker" tabindex="-1">🎯 5. Desempate Determinista Automático (Primary Key Tie-Breaker) <a class="header-anchor" href="#🎯-5-desempate-determinista-automatico-primary-key-tie-breaker" aria-label="Permalink to &quot;🎯 5. Desempate Determinista Automático (Primary Key Tie-Breaker)&quot;">​</a></h2><p>¿Alguna vez te ha pasado que al paginar registros ordenados por <code>created_at</code>, un usuario aparece en la página 1 y vuelve a salir en la página 2?</p><p>Esto ocurre en motores SQL (MySQL, PostgreSQL) cuando varias filas tienen exactamente la misma fecha: el motor no garantiza el orden relativo de los registros idénticos entre una página y la siguiente.</p><h3 id="como-lo-soluciona-el-procesador" tabindex="-1">Cómo lo soluciona el procesador: <a class="header-anchor" href="#como-lo-soluciona-el-procesador" aria-label="Permalink to &quot;Cómo lo soluciona el procesador:&quot;">​</a></h3><p>El procesador detecta automáticamente la clave primaria de tu modelo (<code>id</code>, <code>uuid</code>, etc.) y, si no fue incluida en la petición, <strong>la añade automáticamente como último criterio de desempate</strong>:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- Petición del cliente: ?sort=status</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> asc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">desc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>¡Esto garantiza que cada fila tenga una posición fija e inmutable en todas las páginas!</p><hr><h2 id="🚫-6-proteccion-de-v1-rechazo-de-notacion-de-punto-en-sort" tabindex="-1">🚫 6. Protección de V1: Rechazo de Notación de Punto en Sort <a class="header-anchor" href="#🚫-6-proteccion-de-v1-rechazo-de-notacion-de-punto-en-sort" aria-label="Permalink to &quot;🚫 6. Protección de V1: Rechazo de Notación de Punto en Sort&quot;">​</a></h2><p>En V1, el procesador <strong>rechaza expresamente intentos de ordenar por relaciones</strong> (<code>?sort=roles.name</code>).</p><p><strong>¿Por qué?</strong> Ordenar por relaciones exige aplicar <code>LEFT JOIN</code> que multiplican las filas del modelo principal, rompiendo los cálculos matemáticos del paginador de Laravel. Para preservar la integridad de la paginación, el ordenamiento es exclusivo sobre la tabla base.</p>',39)])])}const g=s(n,[["render",r]]);export{k as __pageData,g as default};
